/**
 * Trello L2: task message + inputsFromPrior → tool arguments for mcp-trello.
 */

/** @param {Array<object>} priorResults @param {number} index */
function priorResultAt(priorResults, index) {
  return (priorResults || [])[index];
}

/**
 * @param {string} path e.g. notion.summary, priorResults[0].artifacts.page_url
 * @param {Array<object>} priorResults
 */
function resolveInputPath(path, priorResults) {
  if (!path) return null;
  const p = path.trim();
  const bracket = p.match(/^priorResults\[(\d+)\]\.(.+)$/);
  if (bracket) {
    const row = priorResultAt(priorResults, Number(bracket[1]));
    return getNested(row, bracket[2]);
  }
  const dot = p.match(/^([a-z0-9_-]+)\.(.+)$/i);
  if (dot) {
    const key = dot[1];
    const row = [...(priorResults || [])].reverse().find((r) => r?.connectorKey === key);
    if (row) return getNested(row, dot[2]);
  }
  return null;
}

function getNested(obj, path) {
  if (!obj || !path) return null;
  const parts = path.split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur == null) return null;
    cur = cur[part];
  }
  if (cur == null) return null;
  return String(cur);
}

/** @param {string} message */
function extractBoardName(message) {
  if (!message) return null;
  const patterns = [
    /(?:на|в)\s+доск(?:е|у)\s+[«"']?(.+?)(?:\s+в\s+список|\s+создай|\s+добавь|$)/iu,
    /(?:board|доска)\s+[«"']?([^«"'\n,.:;]+)/iu,
    /trello[:\s]+[«"']?([^«"'\n,.:;]+)/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim() && m[1].trim().length <= 120) return m[1].trim();
  }
  return null;
}

/** @param {string} value */
function trimListHint(value) {
  if (!value) return null;
  const trimmed = value
    .replace(/\s+на\s+доск(?:е|у)\s+.+$/iu, '')
    .replace(/\s+in\s+board\s+.+$/iu, '')
    .trim();
  return trimmed || null;
}

/** @param {string} message */
function extractTargetListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:в|into)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s+in\s+board|\s*$)/iu,
    /(?:move|перемест(?:и|ить)|перенес(?:и|ти)).+?(?:в|into|to)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim()) return trimListHint(m[1].trim());
  }
  return extractListName(message);
}

/** @param {string} message */
function extractNewListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:переимен(?:уй|ить)|rename).+?(?:в|to|into)\s+[«"']?([^«"'\n,.:;]+)/iu,
    /(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+)[«"']?\s+(?:в|to|into)\s+[«"']?([^«"'\n,.:;]+)/iu,
  ];
  const m1 = message.trim().match(patterns[0]);
  if (m1?.[1]?.trim()) return m1[1].trim();
  const m2 = message.trim().match(patterns[1]);
  if (m2?.[2]?.trim()) return m2[2].trim();
  return null;
}

/** @param {string} message */
function extractListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:создай|добавь|create|add)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s+in\s+board|\s*$)/iu,
    /(?:в|into)\s+список\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
    /(?:list|колонк[ауе])\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
    /#([\w-]+)/,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim() && m[1].trim().length <= 80) return trimListHint(m[1].trim());
  }
  return null;
}

/** @param {string} message */
function extractCardName(message) {
  if (!message) return null;
  const patterns = [
    /(?:перемест(?:и|ить)|перенес(?:и|ти)|move)\s+(?:карточк[ауе]|card)\s+[«"']?([^«"'\n]+?)\s+(?:в|into|to)\s+(?:колонк|список|list)/iu,
    /(?:удали|удалить|delete|remove|убери)\s+(?:карточк[ауе]|card)\s+[«"']?([^«"'\n]+?)(?:\s+на\s+доск|\s+из|\s+from|\s*$)/iu,
    /(?:карточк[ауе]|card)\s+[«"']([^«"']+)[«"']/iu,
    /(?:карточк[ауе]|card)\s+([\p{L}\p{N}_ -]{2,80}?)(?:\s+(?:в|into|to|на)\s+|\s*$)/iu,
    /(?:назови|название)\s+[«"']([^«"']+)[«"']/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim()) return m[1].trim();
  }
  return null;
}

/** @param {string} message */
function extractSearchQuery(message) {
  if (!message) return null;
  const trimmed = message.trim();
  const quoted = trimmed.match(/[«"']([^«"']+)[«"']/);
  if (quoted?.[1]?.trim()) {
    return cleanupSearchQuery(quoted[1].trim());
  }
  const patterns = [
    /(?:найди|найти|поиск|search|find|покаж(?:и)?)\s+(?:карточ(?:ку|ки|ек)|cards?)?\s*(?:про|about|with|с(?:\s+текстом)?)?\s*[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
    /(?:карточ(?:ку|ки|ек)|cards?)\s+(?:про|about|with)?\s*[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
    /(?:про|about)\s+[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
  ];
  for (const re of patterns) {
    const m = trimmed.match(re);
    if (m?.[1]?.trim()) {
      return cleanupSearchQuery(m[1].trim());
    }
  }
  return cleanupSearchQuery(trimmed);
}

/** @param {string} raw */
function cleanupSearchQuery(raw) {
  const cleaned = raw
    .replace(/\b(?:trello|на\s+доск(?:е|у)|доск(?:а|е|у)|board|в\s+trello)\b/giu, ' ')
    .replace(/\b(?:найди|найти|поиск|search|find|покаж(?:и)?|карточ(?:ку|ки|ек)|cards?)\b/giu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return cleaned || null;
}

/**
 * @param {object} task
 * @param {Array<object>} priorResults
 * @param {string} [toolName]
 */
function buildTrelloToolArguments(task, priorResults, toolName) {
  const message = task?.message || '';
  const constraints = task?.constraints || {};
  let description = message;
  const inputs = task?.inputsFromPrior || [];
  const extras = [];

  for (const path of inputs) {
    const val = resolveInputPath(path, priorResults);
    if (val) extras.push(val);
  }

  if (extras.length) {
    description = extras.join('\n');
    if (message && !extras.some((e) => message.includes(e))) {
      description = `${message}\n\n${description}`;
    }
  }

  const board =
    constraints.board || constraints.board_name || constraints.boardName || extractBoardName(message);
  const list =
    constraints.list || constraints.list_name || constraints.listName || extractListName(message);
  const name =
    constraints.name ||
    constraints.card_name ||
    constraints.title ||
    extractCardName(message) ||
    'Задача из чата';

  const normalizedTool = (toolName || '').toLowerCase();

  if (normalizedTool === 'trello_search_cards') {
    let query =
      constraints.query || constraints.q || extractSearchQuery(message) || extractCardName(message);
    if (!query && extras.length) {
      query = extras.join(' ');
    }
    const args = {};
    if (board) args.board_name = board;
    if (query) args.query = query;
    return args;
  }

  if (normalizedTool === 'trello_add_comment') {
    const cardRef =
      constraints.card_id ||
      constraints.cardId ||
      extractCardName(message) ||
      name;
    const text = constraints.desc || constraints.text || description;
    const args = { name: cardRef, desc: text };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_list_lists') {
    const args = {};
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_create_list') {
    const args = { list_name: list || extractListName(message) || 'New list' };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_rename_list') {
    const current =
      constraints.list_name || constraints.listName || extractListName(message) || list;
    const args = {
      list_name: current,
      new_name:
        constraints.new_name ||
        constraints.newName ||
        constraints.name ||
        extractNewListName(message),
    };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_archive_list') {
    const args = { list_name: list || extractListName(message) || 'Archive' };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_move_card') {
    const cardRef =
      constraints.card_id || constraints.cardId || extractCardName(message) || name;
    const target =
      constraints.list_name ||
      constraints.listName ||
      constraints.target_list ||
      extractTargetListName(message) ||
      list;
    const args = { name: cardRef, list_name: target };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_delete_card') {
    const cardRef =
      constraints.card_id || constraints.cardId || extractCardName(message) || name;
    const args = { name: cardRef };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_create_card') {
    const args = {
      list_name: list || 'To Do',
      name,
      desc: description,
      description,
    };
    if (board) args.board_name = board;
    return args;
  }

  const args = {
    list_name: list || 'To Do',
    name,
    desc: description,
    description,
  };
  if (board) args.board_name = board;
  return args;
}


/**
 * Trello L2 mini-router: resolves tool names and delegates invoke to chat-tool-step → mcp-trello.
 */

function matchesSearchIntent(lower) {
  return ['найди', 'поиск', 'search', 'find', 'покаж', 'список карточ'].some((w) =>
    lower.includes(w),
  );
}

function matchesCommentIntent(lower) {
  return ['коммент', 'comment', 'ответь', 'reply'].some((w) => lower.includes(w));
}

function matchesCreateIntent(lower) {
  return CREATE_VERBS.some((w) => lower.includes(w)) || lower.includes('карточк');
}

const CREATE_VERBS = ['создай', 'создать', 'добавь', 'добавить', 'create', 'add card', 'new card'];

function matchesMoveIntent(lower) {
  const hasMoveVerb = ['перемест', 'перенес', 'move', 'перетащ', 'drag'].some((w) =>
    lower.includes(w),
  );
  const hasMoveTarget = /(?:в|into|to)\s+(?:колонк|список|list)\s/.test(lower);
  return hasMoveVerb && (hasMoveTarget || lower.includes('карточ'));
}

function matchesListColumnsIntent(lower) {
  return (
    ['колонк', 'списк', 'lists', 'columns', 'column'].some((w) => lower.includes(w)) &&
    ['покаж', 'список', 'list', 'какие', 'show', 'вывед'].some((w) => lower.includes(w)) &&
    !lower.includes('карточ')
  );
}

function matchesCreateListIntent(lower) {
  return (
    CREATE_VERBS.some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w)) &&
    !lower.includes('карточ')
  );
}

function matchesRenameListIntent(lower) {
  return (
    ['переимен', 'rename'].some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w))
  );
}

function matchesArchiveListIntent(lower) {
  return (
    ['архив', 'archive'].some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w))
  );
}

function matchesDeleteCardIntent(lower) {
  const hasDeleteVerb = ['удали', 'удалить', 'delete', 'remove', 'убери'].some((w) =>
    lower.includes(w),
  );
  const hasCard = lower.includes('карточ') || lower.includes('card');
  return hasDeleteVerb && hasCard;
}

/** @param {string} message */
function resolveTrelloToolName(message) {
  if (!message?.trim()) return null;
  const lower = message.toLowerCase();
  const wantsCreate = CREATE_VERBS.some((w) => lower.includes(w));
  if (matchesSearchIntent(lower) && !wantsCreate && !matchesListColumnsIntent(lower)) {
    return 'trello_search_cards';
  }
  if (matchesMoveIntent(lower)) {
    return 'trello_move_card';
  }
  if (matchesListColumnsIntent(lower)) {
    return 'trello_list_lists';
  }
  if (matchesRenameListIntent(lower)) {
    return 'trello_rename_list';
  }
  if (matchesArchiveListIntent(lower)) {
    return 'trello_archive_list';
  }
  if (matchesDeleteCardIntent(lower)) {
    return 'trello_delete_card';
  }
  if (matchesCreateListIntent(lower)) {
    return 'trello_create_list';
  }
  if (matchesCommentIntent(lower)) {
    return 'trello_add_comment';
  }
  if (matchesCreateIntent(lower)) {
    return 'trello_create_card';
  }
  if (lower.includes('trello')) {
    return 'trello_create_card';
  }
  return null;
}

/** @param {object} step @param {Array<object>} priorResults */
function resolveTrelloInternalSteps(step, priorResults = []) {
  if (step?.toolName) {
    return [
      {
        connectorKey: 'trello',
        toolName: step.toolName,
        arguments: step.arguments || {},
        label: step.label || step.toolName,
      },
    ];
  }

  const task = step?.task;
  if (!task?.message?.trim()) {
    return [];
  }

  const toolName = resolveTrelloToolName(task.message);
  if (!toolName) {
    return [];
  }

  return [
    {
      connectorKey: 'trello',
      toolName,
      arguments: buildTrelloToolArguments(task, priorResults, toolName),
      label: step.label || 'Действие в Trello',
    },
  ];
}

/** Local mock invoke when TRELLO_CONNECTOR_MOCK=true (dev without credentials). */
function buildTrelloMockSummary(args, toolName) {
  const board = args?.board_name || args?.board || 'Roadmap';
  const list = args?.list_name || args?.list || 'To Do';
  const name = args?.name || args?.card_name || 'Карточка';
  const desc = (args?.desc || args?.description || '').trim();
  const preview = desc.length > 200 ? `${desc.slice(0, 200)}…` : desc;
  const n = (toolName || '').toLowerCase();
  if (n.includes('search')) {
    const q = args?.query || preview || name;
    return `Trello (mock): поиск «${q}» на доске ${board}`;
  }
  if (n.includes('comment')) {
    return `Trello (mock): комментарий к карточке «${name}»${preview ? ` — «${preview}»` : ''}`;
  }
  if (n.includes('move')) {
    return `Trello (mock): карточка «${name}» → колонка ${list}`;
  }
  if (n.includes('list_lists') || n.includes('list lists')) {
    return `Trello (mock): колонки на доске ${board}`;
  }
  if (n.includes('create_list')) {
    return `Trello (mock): создана колонка «${list}» на доске ${board}`;
  }
  if (n.includes('rename_list')) {
    return `Trello (mock): колонка «${list}» переименована в «${args?.new_name || args?.name || 'New'}»`;
  }
  if (n.includes('archive_list')) {
    return `Trello (mock): колонка «${list}» архивирована на доске ${board}`;
  }
  if (n.includes('delete_card')) {
    return `Trello (mock): карточка «${name}» удалена`;
  }
  return `Trello (mock): карточка «${name}» → доска ${board}, список ${list}${preview ? ` — «${preview}»` : ''}`;
}


// Parse Trello connector webhook body.
const env = typeof $env !== 'undefined' ? $env : process.env;
const body = $input.first().json.body || $input.first().json;

const aiBase = env.N8N_AI_BASE_URL || 'http://ai:8083/v1/ai';
const mcpBase = env.N8N_MCP_BASE_URL || 'http://mcp:8081/v1/mcp';
const policyBase = env.N8N_POLICY_BASE_URL || 'http://policy:8085/v1/policy';
const aiKey = env.AI_INTERNAL_API_KEY || 'dev-internal-key';
const policyKey = env.POLICY_INTERNAL_API_KEY || 'dev-internal-key';
const mcpKey = env.MCP_INTERNAL_API_KEY || 'dev-internal-key';
const toolStepUrl = env.N8N_TOOL_STEP_WEBHOOK_URL || 'http://n8n:5678/webhook/chat-tool-step';
const trelloMock = env.TRELLO_CONNECTOR_MOCK !== 'false';

const step = body.step;
const priorResults = body.priorResults || [];
const stepIndex = body.stepIndex || 1;
const totalSteps = body.totalSteps || 1;

const base = {
  orgId: body.orgId,
  workspaceId: body.workspaceId,
  userId: body.userId,
  runId: body.runId,
  stepIndex,
  totalSteps,
  aiBase,
  mcpBase,
  policyBase,
  aiKey,
  policyKey,
  mcpKey,
  toolStepUrl,
  trelloMock,
};

if (!step?.connectorKey || step.connectorKey !== 'trello') {
  return [{ json: { ...base, valid: false, error: 'Invalid Trello connector step' } }];
}

const internalSteps = resolveTrelloInternalSteps(step, priorResults);
if (!internalSteps.length) {
  return [{ json: { ...base, valid: false, error: 'Could not resolve Trello tools for task' } }];
}

return [
  {
    json: {
      ...base,
      valid: true,
      priorResults,
      internalSteps,
      connectorLabel: step.label || 'Trello',
    },
  },
];

/**
 * Trello L2: task message + inputsFromPrior → tool arguments for mcp-trello.
 */

/** @param {Array<object>} priorResults @param {number} index */
function priorResultAt(priorResults, index) {
  return (priorResults || [])[index];
}

/**
 * @param {string} path e.g. notion.summary, priorResults[0].artifacts.page_url
 * @param {Array<object>} priorResults
 */
function resolveInputPath(path, priorResults) {
  if (!path) return null;
  const p = path.trim();
  const bracket = p.match(/^priorResults\[(\d+)\]\.(.+)$/);
  if (bracket) {
    const row = priorResultAt(priorResults, Number(bracket[1]));
    return getNested(row, bracket[2]);
  }
  const dot = p.match(/^([a-z0-9_-]+)\.(.+)$/i);
  if (dot) {
    const key = dot[1];
    const row = [...(priorResults || [])].reverse().find((r) => r?.connectorKey === key);
    if (row) return getNested(row, dot[2]);
  }
  return null;
}

function getNested(obj, path) {
  if (!obj || !path) return null;
  const parts = path.split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur == null) return null;
    cur = cur[part];
  }
  if (cur == null) return null;
  return String(cur);
}

/** @param {string} message */
function extractBoardName(message) {
  if (!message) return null;
  const patterns = [
    /(?:на|в)\s+доск(?:е|у)\s+[«"']?(.+?)(?:\s+в\s+список|\s+создай|\s+добавь|$)/iu,
    /(?:board|доска)\s+[«"']?([^«"'\n,.:;]+)/iu,
    /trello[:\s]+[«"']?([^«"'\n,.:;]+)/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim() && m[1].trim().length <= 120) return m[1].trim();
  }
  return null;
}

/** @param {string} value */
function trimListHint(value) {
  if (!value) return null;
  const trimmed = value
    .replace(/\s+на\s+доск(?:е|у)\s+.+$/iu, '')
    .replace(/\s+in\s+board\s+.+$/iu, '')
    .trim();
  return trimmed || null;
}

/** @param {string} message */
function extractTargetListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:в|into)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s+in\s+board|\s*$)/iu,
    /(?:move|перемест(?:и|ить)|перенес(?:и|ти)).+?(?:в|into|to)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim()) return trimListHint(m[1].trim());
  }
  return extractListName(message);
}

/** @param {string} message */
function extractNewListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:переимен(?:уй|ить)|rename).+?(?:в|to|into)\s+[«"']?([^«"'\n,.:;]+)/iu,
    /(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+)[«"']?\s+(?:в|to|into)\s+[«"']?([^«"'\n,.:;]+)/iu,
  ];
  const m1 = message.trim().match(patterns[0]);
  if (m1?.[1]?.trim()) return m1[1].trim();
  const m2 = message.trim().match(patterns[1]);
  if (m2?.[2]?.trim()) return m2[2].trim();
  return null;
}

/** @param {string} message */
function extractListName(message) {
  if (!message) return null;
  const patterns = [
    /(?:создай|добавь|create|add)\s+(?:колонк[ауе]|список|list)\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s+in\s+board|\s*$)/iu,
    /(?:в|into)\s+список\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
    /(?:list|колонк[ауе])\s+[«"']?([^«"'\n,.:;]+?)(?:\s+на\s+доск|\s*$)/iu,
    /#([\w-]+)/,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim() && m[1].trim().length <= 80) return trimListHint(m[1].trim());
  }
  return null;
}

/** @param {string} message */
function extractCardName(message) {
  if (!message) return null;
  const patterns = [
    /(?:перемест(?:и|ить)|перенес(?:и|ти)|move)\s+(?:карточк[ауе]|card)\s+[«"']?([^«"'\n]+?)\s+(?:в|into|to)\s+(?:колонк|список|list)/iu,
    /(?:удали|удалить|delete|remove|убери)\s+(?:карточк[ауе]|card)\s+[«"']?([^«"'\n]+?)(?:\s+на\s+доск|\s+из|\s+from|\s*$)/iu,
    /(?:карточк[ауе]|card)\s+[«"']([^«"']+)[«"']/iu,
    /(?:карточк[ауе]|card)\s+([\p{L}\p{N}_ -]{2,80}?)(?:\s+(?:в|into|to|на)\s+|\s*$)/iu,
    /(?:назови|название)\s+[«"']([^«"']+)[«"']/iu,
  ];
  for (const re of patterns) {
    const m = message.trim().match(re);
    if (m?.[1]?.trim()) return m[1].trim();
  }
  return null;
}

/** @param {string} message */
function extractSearchQuery(message) {
  if (!message) return null;
  const trimmed = message.trim();
  const quoted = trimmed.match(/[«"']([^«"']+)[«"']/);
  if (quoted?.[1]?.trim()) {
    return cleanupSearchQuery(quoted[1].trim());
  }
  const patterns = [
    /(?:найди|найти|поиск|search|find|покаж(?:и)?)\s+(?:карточ(?:ку|ки|ек)|cards?)?\s*(?:про|about|with|с(?:\s+текстом)?)?\s*[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
    /(?:карточ(?:ку|ки|ек)|cards?)\s+(?:про|about|with)?\s*[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
    /(?:про|about)\s+[«"']?(.+?)(?:\s+на\s+доск|\s+в\s+trello|$)/iu,
  ];
  for (const re of patterns) {
    const m = trimmed.match(re);
    if (m?.[1]?.trim()) {
      return cleanupSearchQuery(m[1].trim());
    }
  }
  return cleanupSearchQuery(trimmed);
}

/** @param {string} raw */
function cleanupSearchQuery(raw) {
  const cleaned = raw
    .replace(/\b(?:trello|на\s+доск(?:е|у)|доск(?:а|е|у)|board|в\s+trello)\b/giu, ' ')
    .replace(/\b(?:найди|найти|поиск|search|find|покаж(?:и)?|карточ(?:ку|ки|ек)|cards?)\b/giu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return cleaned || null;
}

/**
 * @param {object} task
 * @param {Array<object>} priorResults
 * @param {string} [toolName]
 */
function buildTrelloToolArguments(task, priorResults, toolName) {
  const message = task?.message || '';
  const constraints = task?.constraints || {};
  let description = message;
  const inputs = task?.inputsFromPrior || [];
  const extras = [];

  for (const path of inputs) {
    const val = resolveInputPath(path, priorResults);
    if (val) extras.push(val);
  }

  if (extras.length) {
    description = extras.join('\n');
    if (message && !extras.some((e) => message.includes(e))) {
      description = `${message}\n\n${description}`;
    }
  }

  const board =
    constraints.board || constraints.board_name || constraints.boardName || extractBoardName(message);
  const list =
    constraints.list || constraints.list_name || constraints.listName || extractListName(message);
  const name =
    constraints.name ||
    constraints.card_name ||
    constraints.title ||
    extractCardName(message) ||
    'Задача из чата';

  const normalizedTool = (toolName || '').toLowerCase();

  if (normalizedTool === 'trello_search_cards') {
    let query =
      constraints.query || constraints.q || extractSearchQuery(message) || extractCardName(message);
    if (!query && extras.length) {
      query = extras.join(' ');
    }
    const args = {};
    if (board) args.board_name = board;
    if (query) args.query = query;
    return args;
  }

  if (normalizedTool === 'trello_add_comment') {
    const cardRef =
      constraints.card_id ||
      constraints.cardId ||
      extractCardName(message) ||
      name;
    const text = constraints.desc || constraints.text || description;
    const args = { name: cardRef, desc: text };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_list_lists') {
    const args = {};
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_create_list') {
    const args = { list_name: list || extractListName(message) || 'New list' };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_rename_list') {
    const current =
      constraints.list_name || constraints.listName || extractListName(message) || list;
    const args = {
      list_name: current,
      new_name:
        constraints.new_name ||
        constraints.newName ||
        constraints.name ||
        extractNewListName(message),
    };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_archive_list') {
    const args = { list_name: list || extractListName(message) || 'Archive' };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_move_card') {
    const cardRef =
      constraints.card_id || constraints.cardId || extractCardName(message) || name;
    const target =
      constraints.list_name ||
      constraints.listName ||
      constraints.target_list ||
      extractTargetListName(message) ||
      list;
    const args = { name: cardRef, list_name: target };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_delete_card') {
    const cardRef =
      constraints.card_id || constraints.cardId || extractCardName(message) || name;
    const args = { name: cardRef };
    if (board) args.board_name = board;
    return args;
  }

  if (normalizedTool === 'trello_create_card') {
    const args = {
      list_name: list || 'To Do',
      name,
      desc: description,
      description,
    };
    if (board) args.board_name = board;
    return args;
  }

  const args = {
    list_name: list || 'To Do',
    name,
    desc: description,
    description,
  };
  if (board) args.board_name = board;
  return args;
}


/**
 * Trello L2 mini-router: resolves tool names and delegates invoke to chat-tool-step → mcp-trello.
 */

function matchesSearchIntent(lower) {
  return ['найди', 'поиск', 'search', 'find', 'покаж', 'список карточ'].some((w) =>
    lower.includes(w),
  );
}

function matchesCommentIntent(lower) {
  return ['коммент', 'comment', 'ответь', 'reply'].some((w) => lower.includes(w));
}

function matchesCreateIntent(lower) {
  return CREATE_VERBS.some((w) => lower.includes(w)) || lower.includes('карточк');
}

const CREATE_VERBS = ['создай', 'создать', 'добавь', 'добавить', 'create', 'add card', 'new card'];

function matchesMoveIntent(lower) {
  const hasMoveVerb = ['перемест', 'перенес', 'move', 'перетащ', 'drag'].some((w) =>
    lower.includes(w),
  );
  const hasMoveTarget = /(?:в|into|to)\s+(?:колонк|список|list)\s/.test(lower);
  return hasMoveVerb && (hasMoveTarget || lower.includes('карточ'));
}

function matchesListColumnsIntent(lower) {
  return (
    ['колонк', 'списк', 'lists', 'columns', 'column'].some((w) => lower.includes(w)) &&
    ['покаж', 'список', 'list', 'какие', 'show', 'вывед'].some((w) => lower.includes(w)) &&
    !lower.includes('карточ')
  );
}

function matchesCreateListIntent(lower) {
  return (
    CREATE_VERBS.some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w)) &&
    !lower.includes('карточ')
  );
}

function matchesRenameListIntent(lower) {
  return (
    ['переимен', 'rename'].some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w))
  );
}

function matchesArchiveListIntent(lower) {
  return (
    ['архив', 'archive'].some((w) => lower.includes(w)) &&
    ['колонк', 'список', 'list', 'column'].some((w) => lower.includes(w))
  );
}

function matchesDeleteCardIntent(lower) {
  const hasDeleteVerb = ['удали', 'удалить', 'delete', 'remove', 'убери'].some((w) =>
    lower.includes(w),
  );
  const hasCard = lower.includes('карточ') || lower.includes('card');
  return hasDeleteVerb && hasCard;
}

/** @param {string} message */
function resolveTrelloToolName(message) {
  if (!message?.trim()) return null;
  const lower = message.toLowerCase();
  const wantsCreate = CREATE_VERBS.some((w) => lower.includes(w));
  if (matchesSearchIntent(lower) && !wantsCreate && !matchesListColumnsIntent(lower)) {
    return 'trello_search_cards';
  }
  if (matchesMoveIntent(lower)) {
    return 'trello_move_card';
  }
  if (matchesListColumnsIntent(lower)) {
    return 'trello_list_lists';
  }
  if (matchesRenameListIntent(lower)) {
    return 'trello_rename_list';
  }
  if (matchesArchiveListIntent(lower)) {
    return 'trello_archive_list';
  }
  if (matchesDeleteCardIntent(lower)) {
    return 'trello_delete_card';
  }
  if (matchesCreateListIntent(lower)) {
    return 'trello_create_list';
  }
  if (matchesCommentIntent(lower)) {
    return 'trello_add_comment';
  }
  if (matchesCreateIntent(lower)) {
    return 'trello_create_card';
  }
  if (lower.includes('trello')) {
    return 'trello_create_card';
  }
  return null;
}

/** @param {object} step @param {Array<object>} priorResults */
function resolveTrelloInternalSteps(step, priorResults = []) {
  if (step?.toolName) {
    return [
      {
        connectorKey: 'trello',
        toolName: step.toolName,
        arguments: step.arguments || {},
        label: step.label || step.toolName,
      },
    ];
  }

  const task = step?.task;
  if (!task?.message?.trim()) {
    return [];
  }

  const toolName = resolveTrelloToolName(task.message);
  if (!toolName) {
    return [];
  }

  return [
    {
      connectorKey: 'trello',
      toolName,
      arguments: buildTrelloToolArguments(task, priorResults, toolName),
      label: step.label || 'Действие в Trello',
    },
  ];
}

/** Local mock invoke when TRELLO_CONNECTOR_MOCK=true (dev without credentials). */
function buildTrelloMockSummary(args, toolName) {
  const board = args?.board_name || args?.board || 'Roadmap';
  const list = args?.list_name || args?.list || 'To Do';
  const name = args?.name || args?.card_name || 'Карточка';
  const desc = (args?.desc || args?.description || '').trim();
  const preview = desc.length > 200 ? `${desc.slice(0, 200)}…` : desc;
  const n = (toolName || '').toLowerCase();
  if (n.includes('search')) {
    const q = args?.query || preview || name;
    return `Trello (mock): поиск «${q}» на доске ${board}`;
  }
  if (n.includes('comment')) {
    return `Trello (mock): комментарий к карточке «${name}»${preview ? ` — «${preview}»` : ''}`;
  }
  if (n.includes('move')) {
    return `Trello (mock): карточка «${name}» → колонка ${list}`;
  }
  if (n.includes('list_lists') || n.includes('list lists')) {
    return `Trello (mock): колонки на доске ${board}`;
  }
  if (n.includes('create_list')) {
    return `Trello (mock): создана колонка «${list}» на доске ${board}`;
  }
  if (n.includes('rename_list')) {
    return `Trello (mock): колонка «${list}» переименована в «${args?.new_name || args?.name || 'New'}»`;
  }
  if (n.includes('archive_list')) {
    return `Trello (mock): колонка «${list}» архивирована на доске ${board}`;
  }
  if (n.includes('delete_card')) {
    return `Trello (mock): карточка «${name}» удалена`;
  }
  return `Trello (mock): карточка «${name}» → доска ${board}, список ${list}${preview ? ` — «${preview}»` : ''}`;
}


// Run internal Trello step (mock or via chat-tool-step).
const prep = $('Parse Connector Task').first().json;
if (!prep.valid) {
  return [
    {
      json: {
        action: 'continue',
        ok: false,
        error: prep.error,
        stepResult: { ok: false, error: prep.error },
      },
    },
  ];
}

const internal = prep.internalSteps[0];
const args = internal.arguments || {};

if (prep.trelloMock) {
  const summary = buildTrelloMockSummary(args, internal.toolName);
  return [
    {
      json: {
        action: 'continue',
        ok: true,
        toolName: internal.toolName,
        summary,
        stepResult: { ok: true, summary },
        artifacts: {
          board_name: args.board_name,
          list_name: args.list_name,
          card_name: args.name,
        },
      },
    },
  ];
}

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: prep.toolStepUrl,
  json: true,
  body: {
    orgId: prep.orgId,
    workspaceId: prep.workspaceId,
    userId: prep.userId,
    runId: prep.runId,
    step: {
      connectorKey: 'trello',
      toolName: internal.toolName,
      arguments: args,
    },
    stepIndex: 1,
    totalSteps: 1,
    priorResults: prep.priorResults || [],
  },
});

if (res.action === 'complete') {
  return [
    {
      json: {
        action: 'complete',
        ok: true,
        toolName: internal.toolName,
        callback: res.callback,
        stepResult: res.stepResult,
      },
    },
  ];
}

const ok = res.stepResult?.ok;
return [
  {
    json: {
      action: 'continue',
      ok: !!ok,
      toolName: internal.toolName,
      summary: res.stepResult?.summary,
      error: res.stepResult?.error,
      stepResult: res.stepResult,
      artifacts: ok
        ? {
            board_name: args.board_name,
            list_name: args.list_name,
            card_name: args.name,
          }
        : undefined,
    },
  },
];
